// Standalone copy of ot::Ip6::Address::FromString for testing
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdlib.h>

#define OT_ERROR_NONE 0
#define OT_ERROR_PARSE 2
#define OT_IP6_ADDRESS_SIZE 16

typedef struct otIp6Address
{
    union {
        uint8_t  m8[OT_IP6_ADDRESS_SIZE];
        uint16_t m16[OT_IP6_ADDRESS_SIZE / sizeof(uint16_t)];
        uint32_t m32[OT_IP6_ADDRESS_SIZE / sizeof(uint32_t)];
    } mFields;
} otIp6Address;

#define VerifyOrExit(x, y) do { if (!(x)) { y; goto exit; } } while(0)
#define SuccessOrExit(x) do { int _r = (x); if (_r != 0) { goto exit; } } while(0)
#define ExitNow(x) do { x; goto exit; } while(0)

static int addressFromString(otIp6Address *addr, const char *aBuf)
{
    int         error  = OT_ERROR_NONE;
    uint8_t *   dst    = reinterpret_cast<uint8_t *>(addr->mFields.m8);
    uint8_t *   endp   = reinterpret_cast<uint8_t *>(addr->mFields.m8 + 15);
    uint8_t *   colonp = NULL;
    const char *colonc = NULL;
    uint16_t    val    = 0;
    uint8_t     count  = 0;
    bool        first  = true;
    bool        hasIp4 = false;
    char        ch;
    uint8_t     d;

    memset(addr->mFields.m8, 0, 16);

    dst--;

    for (;;)
    {
        ch = *aBuf++;
        d  = ch & 0xf;

        if (('a' <= ch && ch <= 'f') || ('A' <= ch && ch <= 'F'))
        {
            d += 9;
        }
        else if (ch == ':' || ch == '\0' || ch == ' ')
        {
            if (count)
            {
                VerifyOrExit(dst + 2 <= endp, error = OT_ERROR_PARSE);
                *(dst + 1) = static_cast<uint8_t>(val >> 8);
                *(dst + 2) = static_cast<uint8_t>(val);
                dst += 2;
                count = 0;
                val   = 0;
            }
            else if (ch == ':')
            {
                VerifyOrExit(colonp == NULL || first, error = OT_ERROR_PARSE);
                colonp = dst;
            }

            if (ch == '\0' || ch == ' ')
            {
                break;
            }

            colonc = aBuf;

            continue;
        }
        else if (ch == '.')
        {
            hasIp4 = true;

            // Do not count bytes of the embedded IPv4 address.
            endp -= 4;
            break;
        }
        else
        {
            VerifyOrExit('0' <= ch && ch <= '9', error = OT_ERROR_PARSE);
        }

        first = false;
        val   = static_cast<uint16_t>((val << 4) | d);
        VerifyOrExit(++count <= 4, error = OT_ERROR_PARSE);
    }

    while (colonp && dst > colonp)
    {
        *endp-- = *dst--;
    }

    while (endp > dst)
    {
        *endp-- = 0;
    }

    if (hasIp4)
    {
        val = 0;

        // Reset the start and end pointers.
        dst  = reinterpret_cast<uint8_t *>(addr->mFields.m8 + 12);
        endp = reinterpret_cast<uint8_t *>(addr->mFields.m8 + 15);

        for (;;)
        {
            ch = *colonc++;

            if (ch == '.' || ch == '\0' || ch == ' ')
            {
                VerifyOrExit(dst <= endp, error = OT_ERROR_PARSE);

                *dst++ = static_cast<uint8_t>(val);
                val    = 0;

                if (ch == '\0' || ch == ' ')
                {
                    // Check if embedded IPv4 address had exactly four parts.
                    VerifyOrExit(dst == endp + 1, error = OT_ERROR_PARSE);
                    break;
                }
            }
            else
            {
                VerifyOrExit('0' <= ch && ch <= '9', error = OT_ERROR_PARSE);

                val = (10 * val) + (ch & 0xf);

                // Single part of IPv4 address has to fit in one byte.
                VerifyOrExit(val <= 0xff, error = OT_ERROR_PARSE);
            }
        }
    }

exit:
    return error;
}
ENDOFFILE
echo "done"

